&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Record payment transactions and bank activities: Ensure timely and accurate bank reconciliations&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Support cost control and invoice approvals: Collaborate with managers to control expenses and handle invoice approvals&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Maintain accurate asset records: Perform asset accounting, reconcile balance sheets, and manage intercompany accounts&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Assistance with the preparation of monthly, quarterly and annual financial statements under HGB and Local GAAP&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
