&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW67286679 BCX8&quot; data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&lt;span class=&quot;EOP SCXW7686985 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559740&amp;quot;:240}&quot;&gt;Initial assessment&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
